cd /workspace; echo ---ZONES; grep -nE 'loa\.config|tracked_paths|^\s*(framework|project|shared):' grimoires/loa/zones.yaml 2>/dev/null | head -20; ls grimoires/loa/zones.yaml 2>&1; echo ---REGEN-SIZE; python3 - <<'PY'
import json,re
loa=open('pr/head/.claude/loa/CLAUDE.loa.md',encoding='utf-8').read()
cj=json.load(open('pr/head/.claude/data/constraints.json'))
why={}
def walk(x):
    if isinstance(x,dict):
        if 'id' in x and 'why' in x: why[x['id']]=x['why']
        for v in x.values(): walk(v)
    elif isinstance(x,list):
        for v in x: walk(v)
walk(cj)
block=re.search(r'<!-- @constraint-generated: start agent_teams_constraints.*?end agent_teams_constraints -->',loa,re.S).group(0)
rows=[l for l in block.splitlines() if l.startswith('| MUST')]
short=[r.split('|')[2].strip() for r in rows]
long=[why[f'C-TEAM-00{i}'] for i in range(1,6)]
delta=sum(len(l.encode())-len(s.encode()) for s,l in zip(short,long))
print('rows',len(rows),'current bytes',len(loa.encode()),'delta',delta,'regenerated approx',len(loa.encode())+delta,'limit 10240')
PY

