cd /workspace; D=grimoires/loa/a2a/audits/2026-10-21; mkdir -p "$D"; TS=$(date -u +%Y-%m-%dT%H:%M:%SZ); cat > "$D/findings.jsonl" <<'EOF'
{"id":"CQ-001","category":"code_quality","criterion":"documentation_coherence","severity":"HIGH","score":3,"file":"head/.claude/loa/CLAUDE.loa.md","line":124,"code_snippet":"<!-- @constraint-generated: start agent_teams_constraints | hash:c020-teamcreate -->","reasoning_trace":"Compared the five rendered C-TEAM rows (CLAUDE.loa.md L126-130) with constraints.json C-TEAM-001..005 why (L1235 onward): rendered text is the trimmed form, registry is the restored form. Ran generate-constraints.sh --validate-only on the head tree: FAIL STALE agent_teams_constraints, exit 1. Measured CLAUDE.loa.md at 10225 B; regenerating the five rows adds 490 B -> 10715 B against LOA_LIMIT 10240 (check-prompt-budget.sh L53). IDR-4 (instruction-diet-revert.bats L62) only asserts the seven C-PROC rows.","finding":"Task 4.8 revert is rendered only for the seven C-PROC rows; the generated agent_teams_constraints block is stale and cannot be regenerated under the budget this PR sets","critique":"The PR claims the twelve rationales carry pre-diet text, but the model-facing artifact still shows the trimmed C-TEAM text, and the merged tree fails generate-constraints.sh --validate-only whichever way the next contributor resolves the budget conflict.","remediation":"Either regenerate the block, raise LOA_LIMIT (and PB-4/PB-6) to cover >= 10715 B, and extend IDR-4 to C-TEAM-001..005; or restore the base C-TEAM why text in constraints.json, drop them from the pre-diet fixture and the len(want)==12 assertion. Add a test that generate-constraints.sh --validate-only exits 0.","confidence":"high","references":["CWE-1068"]}
{"id":"SEC-001","category":"security","criterion":"authorization","severity":"MEDIUM","score":3,"file":"head/.claude/hooks/compliance/implement-gate.sh","line":128,"code_snippet":"implement|/implement|bug|/bug|run|/run|simstim|/simstim)\n    exit 0","reasoning_trace":"Traced the mode source: L115 reads implement_gate.mode from $PROJECT_ROOT/.loa.config.yaml via yq. That file is repo-root, not App Zone (gate exits 0 for it at L107), and no PreToolUse Write/Edit hook in settings.json names it. With the mode set, L123-129 trusts model-authored tool_input.active_skill and exits 0 silently with no RUNNING-state check and no audit.jsonl row. Two model Writes (config, then src/) bypass the ask. The PR's mitigation is that the key is undocumented (IG-11), but the key name is in the hook source.","finding":"The authoritative opt-in is a fence-disable switch reachable by the fenced agent through an unfenced config file","critique":"Severity held at MEDIUM because the damage (an App-Zone write without the ask prompt) is the same class as the Bash-path gap the framework already accepts, and the gate is advisory. It remains the only branch that converts a model-authored field into an allow.","remediation":"Remove the authoritative branch, or require active_skill AND a fresh RUNNING state and emit an audit.jsonl row on every authoritative allow.","confidence":"high","references":["CWE-807","CWE-284"]}
{"id":"CQ-002","category":"code_quality","criterion":"maintainability","severity":"LOW","score":4,"file":"head/tools/check-prompt-budget.sh","line":53,"code_snippet":"SKILL_LIMIT, LOA_LIMIT, PROTO_FAIL, PROTO_WARN = 16384, 10240, 160000, 114688","reasoning_trace":"wc -c on head CLAUDE.loa.md = 10225 B; limit 10240 B leaves 15 B of headroom, so the fix for CQ-001 trips the budget.","finding":"Fifteen bytes of headroom on CLAUDE.loa.md","critique":"Any rationale edit fails the budget check.","remediation":"Size the limit to the reverted content with a stated margin, or document why it is pinned this tightly.","confidence":"high","references":["CWE-1068"]}
{"id":"SEC-002","category":"security","criterion":"input_validation","severity":"LOW","score":4,"file":"head/.claude/scripts/check-permissions.sh","line":237,"code_snippet":"base=\"*${key#\\*}\"; base=\"${base%% *}\"","reasoning_trace":"Traced rule_key output for an exact requirement: key =git push -> base *=git, a key no rule can produce, contradicting the header grammar (L18-26). All current requirements are wildcard-form so no live effect. Probed bash associative-array behaviour with the degenerate key * from Bash(:*): assignment and lookup behave normally.","finding":"Base-wildcard derivation assumes a wildcard requirement key","critique":"Implementation is narrower than its documented grammar.","remediation":"Derive base from ${key#[*=]} or document that requirements are always wildcard-form.","confidence":"high","references":["CWE-697"]}
{"id":"SEC-003","category":"security","criterion":"availability","severity":"LOW","score":4,"file":"head/.claude/scripts/model-adapter.sh","line":656,"code_snippet":"err_file=\"$(mktemp \"${TMPDIR:-/tmp}/model-adapter-stderr.XXXXXX\")\"","reasoning_trace":"Script runs under set -euo pipefail (L33). A failed mktemp aborts before model-invoke runs and before the usual error line, so the caller sees a bare non-zero exit.","finding":"mktemp with no fallback under set -e","critique":"The WARN-forwarding feature becomes a new failure mode for the hop.","remediation":"err_file=$(mktemp ...) || err_file=/dev/null; skip the grep when it is /dev/null.","confidence":"medium","references":["CWE-754"]}
{"id":"DO-001","category":"devops","criterion":"test_coverage","severity":"LOW","score":4,"file":"head/tools/check-prompt-budget.sh","line":53,"reasoning_trace":"LOA_LIMIT moves 9216 -> 10240 but tests/fixtures/prompt-budget/{over,under} are not among the 88 files; if the over tree was sized between 9217 and 10240 B, PB-8 passes a tree it should fail. Unable to assess from the frozen file set.","finding":"Prompt-budget sentinel fixtures not updated with the limit (unverifiable here)","critique":"Worst case is a test false-negative; the review counted this MEDIUM, this audit LOW.","remediation":"Confirm the over sentinel still fails for another reason, or pad it past 10240 B.","confidence":"low","references":["CWE-1068"]}
{"id":"DO-002","category":"devops","criterion":"documentation","severity":"LOW","score":4,"file":"head/README.md","line":24,"reasoning_trace":"README Unreleased entry and migration addendum present; no CHANGELOG.md among the 88 files although the final commit message cites a CHANGELOG figure. The sprint touches a security fence and the permissions checker.","finding":"CHANGELOG entry not in the diff","critique":"Documentation audit expects security-relevant changes in the CHANGELOG.","remediation":"Confirm the CHANGELOG entry lands in the same PR or sits outside the frozen file set.","confidence":"low","references":["OWASP-ASVS-V1.1"]}
EOF
